import{_ as s,l as m,o as i,c as l,v as t,p as o,x as e,d as n,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"波动率是输入不是输出","description":"","frontmatter":{"title":"波动率是输入不是输出","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/vol-as-input.md","filePath":"quant/vol-as-input.md","lastUpdated":1789023840000}'),E={name:"quant/vol-as-input.md"};function B(d,a,g,_,c,u){const r=m("Mermaid");return i(),l("div",null,[a[1]||(a[1]=t('<h1 id="波动率是输入不是输出" tabindex="-1">波动率是输入不是输出 <a class="header-anchor" href="#波动率是输入不是输出" aria-label="Permalink to &quot;波动率是输入不是输出&quot;">​</a></h1><div class="epigraph"><p>BSM 把 $\\sigma$ 当作方程的系数。市场把价格当输入、反解 $\\sigma_{\\mathrm{imp}}$。历史方差是另一套统计量，不是定价引擎的输出。</p><footer>—— 据 Black and Scholes, 1973；Dupire, Pricing with a Smile, Risk, 1994；Gatheral, The Volatility Surface 整理</footer></div><p>上一课<a href="/quant/stochastic-rate-preview">利率不是常数</a>拆开了 \\(r\\) 的三重身份。缺口是 \\(\\sigma\\) 同样被误用：有人从历史收益估计一个数，塞进 Black 当「模型输出的公平价」；有人从期权反解 \\(\\sigma_{\\mathrm{imp}}\\)，又把它当成预测未来已实现波动。本课钉死：在定价数学里 \\(\\sigma\\) 是输入；市场报价把它变成隐含量；已实现二次变差是路径泛函。三者同名，不是同一个对象。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>GBM 课里 \\(\\sigma\\) 进入 SDE 与 PDE，价格 \\(C(\\sigma)\\) 对 \\(\\sigma\\) 严格递增，故给定 \\(C\\) 可反解唯一的 \\(\\sigma_{\\mathrm{imp}}\\)。缺口是解释这个反解：它是<strong>报价的语言</strong>，使不同 \\(K,T\\) 的价格能画在一张波动率曲面上，不是从时间序列估计出来的参数，更不是本课序列要「算出来」的公平波动。历史波动 \\(\\hat\\sigma\\) 是 \\(P\\) 下的统计；定价用 \\(Q\\) 下的输入。把 \\(\\hat\\sigma\\) 填进 Black 得到的数，一般不是市场价。</p><p>微笑：\\(\\sigma_{\\mathrm{imp}}\\) 随 \\(K\\) 变，说明单一 GBM 被市场拒绝。模型可以换成局部波动、随机波动或跳，但每种仍先<strong>输入</strong>一组波动相关量，再输出价格。没有一种把「正确 \\(\\sigma\\)」当作理论推导的终点。</p><h3 id="隐含波动率不是对已实现波动的无偏预测" tabindex="-1">隐含波动率不是对已实现波动的无偏预测 <a class="header-anchor" href="#隐含波动率不是对已实现波动的无偏预测" aria-label="Permalink to &quot;隐含波动率不是对已实现波动的无偏预测&quot;">​</a></h3><p>即使市场有效，\\(\\sigma_{\\mathrm{imp}}^2\\) 对应的是 \\(Q\\) 下的期望二次变差（在确定利率等条件下），与 \\(P\\) 下已实现方差可以有方差风险溢价。用 \\(\\sigma_{\\mathrm{imp}}\\) 去减后面的已实现，得到的是溢价，不是「市场预测误差」的定义。本课程不把溢价做成实证课，只禁止把三个 \\(\\sigma\\) 画等号。</p><p><span class="marginnote">Dupire 局部波动从整个微笑曲面反解 \\(\\sigma_{\\mathrm{loc}}(K,T)\\)，仍然是把价格当输入。曲面不够密或有套利时，反解不合法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>接口三条。(1) 定价：指定 \\(\\sigma\\)（或函数、或过程），输出 \\(V\\)。(2) 报价：指定 \\(V\\)，输出 \\(\\sigma_{\\mathrm{imp}}(K,T)\\)，用 Black 反解，以便插值与比较。(3) 风险：已实现 \\([ \\ln S]_T\\) 沿路径累加，来自二次变差课，是 \\(P\\) 的对象。对冲用的 Vega 是 \\(\\partial V/\\partial\\sigma\\)，对的是输入参数，不是对 \\(\\hat\\sigma\\) 的回归系数。</p><p>无套利约束：蝶式为正 \\(\\Rightarrow\\) 风险中性密度为正；日历价差约束期限方向。这些约束的是价格，翻译成 \\(\\sigma_{\\mathrm{imp}}\\) 曲面的形状。校准必须先满足它们，再谈拟合误差。</p>',12)),(i(),o(h,null,{default:e(()=>[p(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E8%BE%93%E5%85%A5%20sigma%20%E6%88%96%E6%9B%B2%E9%9D%A2%22%5D%20--%3E%20PRICE%5B%22%E5%AE%9A%E4%BB%B7%E5%BC%95%E6%93%8E%22%5D%0A%20%20MKT%5B%22%E5%B8%82%E5%9C%BA%E6%9C%9F%E6%9D%83%E4%BB%B7%22%5D%20--%3E%20IMP%5B%22%E5%8F%8D%E8%A7%A3%E9%9A%90%E5%90%AB%E6%B3%A2%E5%8A%A8%22%5D%0A%20%20PATH%5B%22%E8%B7%AF%E5%BE%84%E4%BA%8C%E6%AC%A1%E5%8F%98%E5%B7%AE%22%5D%20--%3E%20RV%5B%22%E5%B7%B2%E5%AE%9E%E7%8E%B0%E6%B3%A2%E5%8A%A8%22%5D%0A%20%20IMP%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9A%E8%B7%B3%E7%9A%84%E6%8E%A5%E5%8F%A3%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Black 公式对 \\(\\sigma\\) 的单调性让反函数存在，这是语言能成立的数学原因。市场用这门语言说话：交易员报的是 \\(\\sigma_{\\mathrm{imp}}\\) 不是货币价格，但合约结算仍按价格。引擎若输出与市场 \\(\\sigma_{\\mathrm{imp}}\\) 不一致的价格，差额是可交易的。历史估计没有这个直接对应，除非再加一层「如何把 \\(P\\) 的 \\(\\sigma\\) 映射到 \\(Q\\)」——那是不全市场里选 \\(Q\\) 的额外假设。</p><p>局部波动把微笑解释成 \\(\\sigma(S,t)\\)，随机波动把微笑解释成相关的方差过程。它们改变输入的维度，不改变「先输入、后定价」的方向。本课程主干仍用常数 \\(\\sigma\\) 把公式写完；曲面是对照。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不校准 Heston，不写 SVI 参数化细节。不进入限价簿上期权做市的微观结构。后课默认：写 BSM 时 \\(\\sigma\\) 是给定输入；比较市场用 \\(\\sigma_{\\mathrm{imp}}\\)；路径统计用二次变差。下一课<a href="/quant/jump-process-intuition">跳过程直觉</a>说明连续路径假设本身也可以被市场拒绝。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>定价：\\(\\sigma\\) 是输入；市场：\\(\\sigma_{\\mathrm{imp}}\\) 是反解的报价语言。</li><li>历史波动是 \\(P\\) 的统计，默认不等于 \\(Q\\) 的输入。</li><li>微笑否定单一 GBM，但不把「先输入」改成「先输出」。</li><li>Vega 对的是模型输入，不是回归系数。</li><li>出处：Black–Scholes 1973；Dupire 1994。</li></ul>',7))])}const f=s(E,[["render",B]]);export{P as __pageData,f as default};
